$("#faqs").accordion({
  collapsible: true,
  active: false,
  event: "mouseover",
  heightStyle: "content",
});

$("#confirm").dialog({
  modal: true,
  buttons: {
    Delete: function() {
      $("#result").text("Deleted");
      $(this).dialog("close");
    },
    Cancel: function() {
      $("#result").text("Cancelled");
      $(this).dialog("close");
    },
  },
});

$("#checkin, #checkout").datepicker();
$("#checkin").datepicker("setDate", new Date());
$("#nights").click( () => {
  const start = $("#checkin").datepicker("getDate");
  const end = $("#checkout").datepicker("getDate");
  const nights = Math.round((end - start) / (24 * 60 * 60 * 1000));
  $("#count").text(nights);
});

