$.fn.truncate = function(options) {
  const settings = $.extend({ length: 20, ending: "…" }, options);
  return this.each( function() {
    const text = $(this).text();
    if (text.length > settings.length) {
      $(this).text(text.substring(0, settings.length) + settings.ending);
    }
  });
};
